(()=>{
'use strict';
const root=document.getElementById('kyoto-cinema');
const images={"kyoto": "data:image/webp;base64,", "train": "data:image/webp;base64,", "orbit": "data:image/webp;base64,", "snow": "data:image/webp;base64,", "ramen": "data:image/webp;base64,"};
const $=s=>root.querySelector(s),$$=s=>Array.from(root.querySelectorAll(s));
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=name=>`<i data-lucide="${name}" aria-hidden="true"></i>`;
const icons=()=>lucide.createIcons({attrs:{width:18,height:18}});
const backgrounds=[{id:'kyoto',title:'Киото после дождя'},{id:'train',title:'Ночной Токио'},{id:'orbit',title:'Тихая орбита'},{id:'snow',title:'Снежные горы'},{id:'ramen',title:'Тёплый вечер'}];
const packages={youtube:'app.smarttube.fdroid',kodi:'org.xbmc.kodi'};
let data={apps:[],inputs:[],vpn:false,mediaPermission:false,continue:[],subscriptions:[]};
let offsets={continue:0,subscriptions:0},panelType='',returnFocus=null,lastActivity=Date.now(),paused=false;
let design={background:'kyoto',motion:true,rain:true,darkness:18};
try{Object.assign(design,JSON.parse(Kyoto.loadDesign()));}catch(e){}
function save(){Kyoto.saveDesign(JSON.stringify(design));}
function paint(){
 const bg=backgrounds.find(b=>b.id===design.background)||backgrounds[0];
 design.background=bg.id;root.style.setProperty('--kc-scene',`url('${images[bg.id]}')`);
 root.style.setProperty('--kc-darkness',String(Math.max(0,Math.min(55,design.darkness))/100));
 root.classList.toggle('still',!design.motion||paused);
 $('.kc-rain').style.display=design.rain&&['kyoto','train'].includes(bg.id)?'':'none';
 $('.kc-wallpaper-label').textContent=bg.title;
}
function clock(){
 const now=new Date();$('.kc-homeclock').textContent=now.toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'});
 $('.kc-homedate').textContent=now.toLocaleDateString('ru-RU',{weekday:'long',day:'numeric',month:'long'});
}
function cards(){
 for(const row of ['continue','subscriptions']){
  const shelf=$(`[data-row="${row}"]`),all=data[row]||[];
  offsets[row]=Math.max(0,Math.min(offsets[row],Math.max(0,all.length-4)));const offset=offsets[row];
  shelf.querySelector('.kc-shelfback').disabled=offset===0;shelf.querySelector('.kc-shelfnext').disabled=offset+4>=all.length;
  if(!all.length){
   shelf.querySelector('.kc-cards').innerHTML=`<div class="kc-empty"><span>${data.mediaPermission?(row==='continue'?'Здесь появятся незавершённые видео':'Подписки ещё не подключены'):'Ваши видео на главном экране'}</span>${!data.mediaPermission?'<button class="kc-quick" data-action="permission">Разрешить доступ</button>':''}</div>`;
  }else shelf.querySelector('.kc-cards').innerHTML=all.slice(offset,offset+4).map(v=>`<button class="kc-card" data-video="${escape(v.key)}" aria-label="${escape(v.title)}, ${escape(v.source)}"><span class="kc-thumb kc-live-thumb ${v.poster?'is-poster':''}"><img src="${escape(v.art)}" alt=""><span class="kc-provider">${escape(v.source)}</span>${v.duration?`<span class="kc-cardtime">${format(v.duration)}</span>`:''}${v.duration&&v.position?`<span class="kc-progress"><i style="width:${Math.min(100,v.position/v.duration*100)}%"></i></span>`:''}</span><span class="kc-cardname">${escape(v.title)}</span><span class="kc-cardmeta">${v.position?'Продолжить с '+format(v.position):escape(v.source)}</span></button>`).join('');
 }
 icons();
}
function format(n){const s=Math.max(0,Math.floor(n)),h=Math.floor(s/3600),m=Math.floor(s/60)%60;return (h?`${h}:${String(m).padStart(2,'0')}`:String(m))+':'+String(s%60).padStart(2,'0');}
function option(symbol,title,action,extra=''){return `<button class="kc-option" data-action="${action}">${icon(symbol)}<span>${escape(title)}</span>${extra}</button>`;}
function close(){if($('.kc-overlay').hidden)return;$('.kc-overlay').hidden=true;$('.kc-content').inert=false;panelType='';if(returnFocus?.isConnected)returnFocus.focus();}
function panel(type,remember=true){
 if(type==='sleep'){Kyoto.timer();return;}
 if(remember)returnFocus=document.activeElement;panelType=type;
 const names={apps:'Все приложения',cast:'Трансляция',vpn:'VPN',hdmi:'HDMI',settings:'Атмосфера',wallpaper:'Фон'};
 $('#kc-panel-title').textContent=names[type]||'';let html='';
 if(type==='cast')html=option('gamepad-2','Steam Link','steamlink')+option('cast','Трансляция экрана','screen-cast');
 if(type==='apps')html=`<div class="kc-app-grid">${data.apps.map(a=>`<button class="kc-real-app" data-launch="${escape(a.package)}"><img src="${escape(a.icon)}" alt=""><span>${escape(a.name)}</span></button>`).join('')}</div>`;
 if(type==='vpn')html=`<div class="kc-statushero">${icon(data.vpn?'shield-check':'shield')}<span>${data.vpn?'Подключено':'Отключено'}</span></div>`+option('power',data.vpn?'Отключить':'Подключить','vpn')+option('sliders-horizontal','Настройки Happ','happ');
 if(type==='hdmi')html=data.inputs.map((v,i)=>`<button class="kc-option" data-input="${i}">${icon('monitor')}<span>${escape(v.name)}<small>${v.connected?'Подключён':'Нет сигнала'}</small></span></button>`).join('');
 if(type==='settings')html=option('image','Фон','wallpaper')+option('wind','Движение фона','motion',`<b class="kc-switch ${design.motion?'on':''}"></b>`)+option('cloud-rain','Дождь','rain',`<b class="kc-switch ${design.rain?'on':''}"></b>`)+`<label>Затемнение<input class="kc-dim" type="range" min="0" max="55" value="${design.darkness}" aria-label="Затемнение фона"></label>`+option('moon','Ночной режим','night')+option('history',data.youtubeProgress?'Продолжение YouTube включено':'Включить продолжение YouTube','youtube-progress')+option('settings','Настройки телевизора','settings')+option('log-out','Выйти из Kyoto','exit');
 if(type==='wallpaper')html=`<div class="kc-wallpaper-grid">${backgrounds.map(b=>`<button class="kc-wallpaper" data-wallpaper="${b.id}" aria-pressed="${b.id===design.background}"><span class="kc-wallpaper-art" style="background-image:url('${images[b.id]}')"></span><span>${b.title}</span></button>`).join('')}</div>`;
 $('.kc-panelbody').innerHTML=html;$('.kc-overlay').hidden=false;$('.kc-content').inert=true;icons();(type==='cast'?$('.kc-panelbody button'):$('.kc-close')).focus();
}
window.kyotoData=next=>{
 const active=document.activeElement;
 const focusedVideo=active?.dataset?.video,focusedAction=active?.dataset?.action;
 data=next;data.inputs.sort((a,b)=>a.name.localeCompare(b.name,'ru',{numeric:true}));$('.kc-dot').classList.toggle('on',data.vpn);$('.kc-vpn').setAttribute('aria-label',data.vpn?'VPN подключён':'VPN отключён');
 cards();if(panelType==='vpn'||panelType==='apps'||panelType==='hdmi')panel(panelType,false);
 else if(focusedVideo!==undefined)$$('[data-video]').find(v=>v.dataset.video===focusedVideo)?.focus();
 else if(focusedAction)$(`[data-action="${focusedAction}"]`)?.focus();
 paint();
};
window.kyotoPoster=(key,art)=>{
 for(const row of ['continue','subscriptions'])for(const v of data[row]||[])if(v.key===key){v.art=art;v.poster=true;}
 for(const card of $$('[data-video]'))if(card.dataset.video===key){card.querySelector('img').src=art;card.querySelector('.kc-thumb').classList.add('is-poster');}
};
window.kyotoPause=()=>{paused=true;paint();};
window.kyotoResume=()=>{paused=false;lastActivity=Date.now();$('.kc-wake').hidden=true;$('.kc-content').inert=!!panelType;root.classList.remove('is-idle');paint();};
function wake(){lastActivity=Date.now();$('.kc-wake').hidden=true;root.classList.remove('is-idle');$('.kc-content').inert=false;paint();$('.kc-quick').focus();}
window.kyotoBack=()=>{if(!$('.kc-wake').hidden)wake();else if(panelType)close();else if($('.kc-content').scrollTop>0){$('.kc-content').scrollTo({top:0,behavior:'smooth'});$('[data-app="youtube"]').focus();}else Kyoto.exit();};
window.kyotoActivate=()=>{if(!$('.kc-wake').hidden){wake();return;}const active=document.activeElement;if(active?.tagName==='BUTTON')active.click();};
root.addEventListener('click',event=>{
 lastActivity=Date.now();root.classList.remove('is-idle');
 const b=event.target.closest('button');if(!b)return;
 if(b.matches('.kc-wake')){wake();return;}
 if(b.dataset.app){Kyoto.launch(packages[b.dataset.app]);return;}
 if(b.dataset.launch){Kyoto.launch(b.dataset.launch);return;}
 if(b.dataset.panel){panel(b.dataset.panel);return;}
 if(b.dataset.video!==undefined){Kyoto.video(b.dataset.video);return;}
 if(b.dataset.input!==undefined){const input=data.inputs[Number(b.dataset.input)];if(input)Kyoto.hdmi(input.id);return;}
 if(b.dataset.wallpaper){design.background=b.dataset.wallpaper;paint();save();$$('.kc-wallpaper').forEach(w=>w.setAttribute('aria-pressed',String(w.dataset.wallpaper===design.background)));return;}
 if(b.matches('.kc-close,.kc-scrim')){close();return;}
 if(b.matches('.kc-shelfnext,.kc-shelfback')){const row=b.closest('[data-row]').dataset.row;offsets[row]+=b.matches('.kc-shelfnext')?1:-1;cards();return;}
 const action=b.dataset.action;
 if(action==='permission')Kyoto.allowMedia();
 if(action==='youtube-progress')Kyoto.allowYouTubeProgress();
 if(action==='refresh')Kyoto.refreshData();
 if(action==='vpn'){b.disabled=true;Kyoto.vpn(!data.vpn);}
 if(action==='happ')Kyoto.launch('com.happproxy');
 if(action==='steamlink')Kyoto.launch('com.valvesoftware.steamlink');
 if(action==='screen-cast')Kyoto.cast();
 if(action==='wallpaper')panel('wallpaper',false);
 if(action==='settings')Kyoto.systemSettings();
 if(action==='exit')Kyoto.exit();
 if(action==='motion'||action==='rain'){design[action]=!design[action];paint();save();panel('settings',false);}
 if(action==='night'){design.darkness=40;design.motion=false;paint();save();panel('settings',false);}
});
root.addEventListener('input',e=>{if(e.target.matches('.kc-dim')){design.darkness=Number(e.target.value);paint();save();}});
root.addEventListener('keydown',e=>{
 lastActivity=Date.now();root.classList.remove('is-idle');
 if(!$('.kc-wake').hidden){e.preventDefault();wake();return;}
 if(e.key==='Escape'||e.key==='Backspace'){e.preventDefault();window.kyotoBack();return;}
 if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key))return;
 // A horizontal slider owns Left/Right; Up/Down still navigate the settings list.
 if(e.target.matches('input')&&(!e.target.matches('input[type="range"]')||['ArrowLeft','ArrowRight'].includes(e.key)))return;
 e.preventDefault();
 if(!panelType&&e.target.matches('[data-video]')&&['ArrowLeft','ArrowRight'].includes(e.key)){
  const shelf=e.target.closest('[data-row]'),row=shelf.dataset.row,visible=Array.from(shelf.querySelectorAll('[data-video]')),index=visible.indexOf(e.target);
  if(e.key==='ArrowRight'&&index===visible.length-1&&offsets[row]+4<data[row].length){offsets[row]+=4;cards();shelf.querySelector('[data-video]')?.focus();return;}
  if(e.key==='ArrowLeft'&&index===0&&offsets[row]>0){offsets[row]=Math.max(0,offsets[row]-4);cards();const previous=shelf.querySelectorAll('[data-video]');previous[previous.length-1]?.focus();return;}
 }
 const area=panelType?$('.kc-panel'):$('.kc-content');
 const items=Array.from(area.querySelectorAll('button:not(:disabled),input')).filter(x=>x.getClientRects().length);
 const src=document.activeElement;if(!items.includes(src)){items[0]?.focus();return;}
 const a=src.getBoundingClientRect(),ax=a.x+a.width/2,ay=a.y+a.height/2;let best=null,score=Infinity;
 for(const el of items){if(el===src)continue;const b=el.getBoundingClientRect(),dx=b.x+b.width/2-ax,dy=b.y+b.height/2-ay,h=e.key==='ArrowLeft'||e.key==='ArrowRight',p=h?dx:dy,s=h?dy:dx,sign=(e.key==='ArrowLeft'||e.key==='ArrowUp')?-1:1;if(p*sign<5)continue;const val=Math.abs(p)+Math.abs(s)*3;if(val<score){score=val;best=el;}}
 best?.focus();best?.scrollIntoView({block:'nearest'});
});
root.addEventListener('pointerdown',()=>{lastActivity=Date.now();root.classList.remove('is-idle');});
for(let i=0;i<24;i++){let r=document.createElement('span');r.style.left=(i*37%101)+'%';r.style.animationDelay=-(i*.17)+'s';r.style.animationDuration=(1.8+(i%7)*.15)+'s';$('.kc-rain').append(r);}
setInterval(()=>{
 clock();if(paused)return;const idle=Date.now()-lastActivity;root.classList.remove('is-idle');
 // The Android dream owns black-screen entry and standby, including outside this WebView.
},1000);
cards();paint();clock();icons();
})();
